    """Copy the marked-color motif to every translated position lying on zeros."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    # The marked motif is the rarest color in each demonstrated input.
    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    motif = [(r-r0, c-c0) for r, c in points]
    mh, mw = r1-r0+1, c1-c0+1
    out = [row[:] for row in grid]
    # Stamp wherever every motif cell overlays background zero; retain originals.
    for ar in range(h-mh+1):
        for ac in range(w-mw+1):
            if all(grid[ar+dr][ac+dc] == 0 for dr, dc in motif):
                for dr, dc in motif:
                    out[ar+dr][ac+dc] = color
    return out
