def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    if not pts:
        return out
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = [(r-r0,c-c0) for r,c in pts]
    for ar in range(h-(r1-r0+1)+1):
        for ac in range(w-(c1-c0+1)+1):
            if all(grid[ar+dr][ac+dc] == 0 for dr,dc in shape):
                for dr,dc in shape:
                    out[ar+dr][ac+dc] = marker
    return out
